const platform = $('Webhook').first().json.query.platform || '';
const country  = $('Webhook').first().json.query.country  || '';
const brand    = $('Webhook').first().json.query.brand    || '';

const allRows = $input.all();

const filtered = allRows.filter(item => {
  const r = item.json;
  const matchPlatform = !platform || (r.platform || '').toLowerCase() === platform.toLowerCase();
  const matchCountry  = !country  || (r.country  || '').toLowerCase() === country.toLowerCase();
  const matchBrand    = !brand    || (r.brand     || '').toLowerCase() === brand.toLowerCase();
  return matchPlatform && matchCountry && matchBrand;
});

const contacts = filtered.map(item => ({
  id:              String(item.json.row_number || item.json.id || ''),
  contactName:     item.json.contactName || item.json.name || '',
  company:         item.json.company     || '',
  phone:           item.json.phone || item.json.whatsapp || item.json['WhatsApp'] || item.json.mobile || '',
  email:           item.json.email       || '',
  category:        item.json.category    || '',
  source:          item.json.source      || '',
  platform:        item.json.platform    || '',
  country:         item.json.country     || '',
  brand:           item.json.brand       || '',
  productInterest: item.json.productInterest || item.json['Product Interest'] || ''
}));

return [{ json: { contacts } }];
